prog = '''def transform(grid):
    from collections import Counter

    def comps(g):
        seen = set(); out = []
        for i in range(len(g)):
            for j in range(len(g[0])):
                if g[i][j] and (i, j) not in seen:
                    st = [(i, j)]; cells = []; seen.add((i, j))
                    while st:
                        r, c = st.pop(); cells.append((r, c))
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            a, b = r + dr, c + dc
                            if 0 <= a < len(g) and 0 <= b < len(g[0]) and g[a][b] and (a, b) not in seen:
                                seen.add((a, b)); st.append((a, b))
                    out.append(cells)
        return out

    def tinfo(cells):
        rs = [r for r, c in cells]; cs = [c for r, c in cells]
        rc = Counter(rs)
        barrow = [r for r, n in rc.items() if n == 3][0]
        stem = [(r, c) for r, c in cells if r != barrow][0]
        orient = 'up' if stem[0] < barrow else 'down'
        return (orient, barrow, stem[1])

    slots = {'up': [(0, 0), (2, 0), (0, 2), (2, 2)],
             'down': [(0, 3), (2, 3), (0, 5), (2, 5)]}
    out = [[0] * 6 for _ in range(3)]
    for cls, val in (('up', 3), ('down', 1)):
        group = sorted([t for t in (tinfo(c) for c in comps(grid)) if t[0] == cls],
                       key=lambda t: (t[1], t[2]))
        for t, (r, c) in zip(group, slots[cls]):
            out[r][c] = val
    return out
'''

